class Solution:
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []
        phone = {
            "2": "abc", "3": "def", "4": "ghi",
            "5": "jkl", "6": "mno", "7": "pqrs",
            "8": "tuv", "9": "wxyz",
        }
        answers = []
        path = []
        def backtrack(index: int) -> None:
            if index == len(digits):
                answers.append("".join(path))
                return
            for letter in phone[digits[index]]:
                path.append(letter)
                backtrack(index + 1)
                path.pop()
        backtrack(0)
        return answers
```

