class Solution:
    def totalNQueens(self, n: int) -> int:
        columns = set()
        diag_down = set()
        diag_up = set()
        def backtrack(row: int) -> int:
            if row == n:
                return 1
            total = 0
            for col in range(n):
                down = row - col
                up = row + col
                if col in columns:
                    continue
                if down in diag_down:
                    continue
                if up in diag_up:
                    continue
                columns.add(col)
                diag_down.add(down)
                diag_up.add(up)
                total += backtrack(row + 1)
                columns.remove(col)
                diag_down.remove(down)
                diag_up.remove(up)
            return total
        return backtrack(0)
